import meta from "@/data/image-meta.json";

type Meta = { w: number; h: number; blur: string };
const table = meta as Record<string, Meta>;

/** Blur placeholder + intrinsic size for a /public image, generated by `npm run images:blur`. */
export function imageMeta(src: string): Partial<Meta> {
  return table[src] ?? {};
}

export function blurProps(src: string) {
  const m = table[src];
  return m ? ({ placeholder: "blur" as const, blurDataURL: m.blur }) : {};
}
